function rows(s){if(lists[s.id])return lists[s.id];return (s.ui.rows||[]).map(r=>r.map(v=>String(v).replaceAll('—','미등록').replaceAll('국가 예시','국가 미등록').replaceAll('기간 협의','기간 미등록').replaceAll('시간 예시','14:00').replaceAll('시각 예시','2026-10-02 14:00').replaceAll('단위 협의','금액 미등록').replaceAll('원통화별','USD').replaceAll('환산 기준 필요','환산 미적용').replaceAll('분모 표시','기준 미등록').replaceAll('분모 확인','기준 미등록').replaceAll('척도 협의','미집계')))}
function filterOpts(t){if(t==='이동상태')return ['전체',...travelStages];if(t==='검수 상태')return ['전체','대기','승인','반려'];if(/상태|승인|여부/.test(t))return ['전체','준비','운영','종료','승인','대기','반려','출석','미출석'];if(/유형|구매.*수출|상담 구분/.test(t))return ['전체','구매','수출'];if(/역할|국내.*해외.*통역|참가자/.test(t))return ['전체','국내바이어','해외바이어','통역원'];if(/연도/.test(t))return ['전체','2026','2025'];if(/행사/.test(t))return ['전체','G-FAIR KOREA 2026','G-FAIR KOREA 2025'];return null}
