function dash(s){if(s.id==='MON-07'){const rr=jRows({...s,id:'JNL-07'});return `${head(s)}<div class="kpis">${[['제출 일지',rr.length],['승인 완료',rr.filter(j=>j.status==='승인 완료').length],['검수 대기',rr.filter(j=>j.status==='검수 대기').length],['기기 초안',savedAt?1:0]].map(([t,v])=>`<article class="kpi"><div class="kpi-label">${t}</div><div class="kpi-value">${v}<small>건</small></div></article>`).join('')}</div><div class="notice">본인 상담 기준 · 현재 행사 · 예시 데이터</div>${A('JNL-07','내 상담일지','btn primary')}`}
const buy=s.id==='MON-02'||kind==='구매',exp=s.id==='MON-03'||kind==='수출',values=buy?[168,28,132]:exp?[318,55,252]:[486,83,384];return `${head({...s,title:s.id==='MON-01'?'오늘의 상담 현황':s.title},B('refresh','새로고침'))}${sub(s)}${s.id==='MON-01'||s.id==='STA-01'?`<div class="toolbar"><div class="tabs">${['전체','구매','수출'].map(k=>B('kind',k,'btn '+(kind===k?'primary':''),`data-kind="${k}" aria-pressed="${kind===k}"`)).join('')}</div>${F('조회일',I('date','date','2026-10-02','id="dashboard-date"'))}<span class="small" id="updated">기준시각 2026-10-02 14:32 · 예시</span></div>`:''}<div class="kpis">${[['제출된 상담일지',values[0],'구매·수출 제출 기준'],['검수 대기',values[1],'담당자 검수 대기'],['승인 완료',values[2],'승인 기준 예시'],['현장 매칭 완료',92,'전체 대상 108건']].map(([t,v,n])=>`<article class="kpi"><div class="kpi-label">${t}</div><div class="kpi-value">${v}<small>건</small></div><div class="kpi-note">${n}</div></article>`).join('')}</div><div class="columns"><section class="panel pad"><h2>상담일지 처리 현황</h2><div class="legend" style="margin-top:20px"><span><i class="blue"></i>승인 완료</span><span><i class="gold"></i>검수 대기</span><span><i class="rose"></i>반려</span></div>${!exp?'<div class="barlabel"><strong>구매상담</strong><span>168건</span></div><div class="bar" role="img" aria-label="구매 승인 132건 대기 28건 반려 8건"><span class="blue" style="width:78.57%">132</span><span class="gold" style="width:16.67%">28</span><span class="rose" style="width:4.76%"></span></div>':''}${!buy?'<div class="barlabel"><strong>수출상담</strong><span>318건</span></div><div class="bar" role="img" aria-label="수출 승인 252건 대기 55건 반려 11건"><span class="blue" style="width:79.25%">252</span><span class="gold" style="width:17.3%">55</span><span class="rose" style="width:3.45%"></span></div>':''}<div class="money">${!exp?'<div><small>구매상담액</small><strong>3.2 <small>억원</small></strong></div>':''}${!buy?'<div><small>수출상담액</small><strong>1.8 <small>백만 USD</small></strong></div>':''}</div><p class="small" style="margin-top:15px">승인 일지 예시 · 통화별 표시</p></section><section class="panel pad"><h2>현장 운영 현황</h2>${[['국내바이어 출석','42','48명','MON-05'],['해외바이어 도착','96','108명','PRE-01'],['통역원 출석','64','70명','MON-06'],['현장 매칭 완료','92','108건','MON-04']].map(([t,v,n,id])=>`<a class="fieldstat" href="#${id}"><span>${t}</span><strong>${v} <small>/ ${n}</small></strong></a>`).join('')}<div class="notice amber" style="margin:15px 0 0">현장 매칭 미완료 16건</div></section></div><section class="panel" style="margin-top:20px"><div class="panelhead"><h2>${s.id.startsWith('STA')?'유형별 성과 집계':'최근 제출된 상담일지'}</h2>${A(s.id.startsWith('STA')?'STA-02':'JNL-01','전체 보기','btn ghost')}</div>${s.id.startsWith('STA')?'<div class="tablewrap"><table><thead><tr><th>유형</th><th>상담건수</th><th>승인건수</th><th>상담액</th></tr></thead><tbody><tr><td>구매</td><td>168</td><td>132</td><td>3.2억원</td></tr><tr><td>수출</td><td>318</td><td>252</td><td>1.8백만 USD</td></tr></tbody></table></div>':jTable(journals.filter(j=>!buy&&!exp||j.type===(buy?'구매':'수출')).slice(0,3))}</section>${s.id.startsWith('STA')?`<div class="actions">${actionButtons(s)}</div>`:''}`}
function draftState(){return `<div class="notice ${connected()?'':'amber'}" id="connection-notice">${connected()?'온라인 · 서버 연결 전 검토용 화면':'오프라인 · 기기 초안으로 작성할 수 있습니다.'}</div><p class="save-state" id="save-state">${savedAt?'기기 임시저장 '+E(savedAt):'기기 저장 전'}</p>`}
function write(s){if(s.id==='JNL-04')draft.type='구매';if(s.id==='JNL-05')draft.type='수출';const d=draft,out=s.id==='JNL-06';return `${head({...s,title:d.type+'상담일지 작성'})}<div class="steps"><a href="#${d.type==='구매'?'JNL-04':'JNL-05'}" class="${!out?'active':''}">1 상담 내용</a><hr><a href="#JNL-06" class="${out?'active':''}">2 성과·제출</a></div>${draftState()}<div class="companycard"><span class="booth">${E(d.booth)}</span><div><strong>${E(d.company)}</strong><small>생활용품 · 친환경 주방용품 · 예시</small></div>${A('ENT-01','기업 변경','btn ghost')}</div><form id="draft-form" class="formgrid">${out?`${F('상담액',I('amount','number',d.amount,'min="0" step="any" inputmode="decimal" required'),true)}${F('통화',`<select name="currency">${O(d.type==='구매'?['KRW']:['USD','EUR','KRW'],d.currency)}</select>`)}${F('계약추진액',I('contract','number',d.contract,'min="0" step="any" inputmode="decimal"'))}${F('후속조치',`<textarea name="followup" placeholder="견적서 전달, 샘플 검토 등">${E(d.followup)}</textarea>`)}${d.type==='수출'?F('MOU 진행 여부',`<select name="mou">${O(['해당 없음','검토 중','체결 예정','체결 완료'],d.mou)}</select>`):''}<label class="check"><input name="confirm" type="checkbox" required>상담내용과 금액을 확인했습니다.</label>`:`${F('작성자',I('writer','text',d.type==='구매'?'국내바이어 A':'통역원 A','readonly class="readonly"'))}${d.type==='수출'?F('담당 해외바이어','<select name="buyer"><option>해외바이어 A</option></select>'):''}${F('상담일시',I('date','datetime-local',d.date,'required'),true)}${F('상담품목',`<select name="category">${O(['생활용품','식품','뷰티','산업용품'],d.category)}</select>`)}${F('상담내용',`<textarea name="content" placeholder="상담내용과 바이어 관심사항을 작성해 주세요." required>${E(d.content)}</textarea>`,true,true)}<div class="field wide"><span>관심품목·후속조치 태그</span><div class="chips">${['샘플 검토','견적 요청','후속 미팅','유통 상담'].map(t=>`<label><input type="checkbox" name="tags" value="${t}" ${d.tags.includes(t)?'checked':''}>${t}</label>`).join('')}</div></div><div class="field wide"><span>명함 이미지</span>${image?`<img class="imagepreview" src="${image.url}" alt="첨부한 명함 미리보기"><small>${E(image.name)}</small>`:'<span class="hint">촬영하거나 이미지를 첨부해 주세요.</span>'}<input id="draft-image" type="file" accept="image/*" capture="environment" aria-label="명함 이미지 촬영 또는 선택">${image?B('remove-image','첨부 제거','btn ghost'):''}</div>`}<div class="formfooter wide">${A(out?(d.type==='구매'?'JNL-04':'JNL-05'):'JNL-07',out?'이전':'목록')}${B('save','임시저장')}<button type="submit" class="btn primary">${out?'검토용 제출':'성과 입력'}</button></div></form><p class="small">작성 중 30초마다 이 기기에 임시저장합니다. 서버 제출은 연계 후 이용할 수 있습니다.</p>`}
function save(){const f=document.getElementById('draft-form');if(f){const fd=new FormData(f);for(const k of ['date','content','category','amount','contract','currency','followup','mou','buyer'])if(fd.has(k))draft[k]=fd.get(k);if(current!=='JNL-06')draft.tags=fd.getAll('tags')}try{savedAt=new Date().toLocaleTimeString('ko-KR',{hour12:false});sessionStorage.setItem('gfair-draft',JSON.stringify({...draft,savedAt}));const t=document.getElementById('save-state');if(t)t.textContent='기기 임시저장 '+savedAt;return true}catch{toast('기기 저장을 사용할 수 없습니다. 작성 화면을 유지해 주세요.');return false}}
function sync(s){return `${head(s)}${draftState()}<section class="panel pad"><h2>이 기기에 저장된 초안</h2><dl class="detaildata"><dt>초안번호</dt><dd>${draft.id}</dd><dt>상담기업</dt><dd>${E(draft.company)}</dd><dt>최근 저장</dt><dd>${savedAt||'저장 전'}</dd><dt>서버 동기화</dt><dd>${badge('서버 연결 전')}</dd><dt>제출 상태</dt><dd>${badge(submitted?'제출 상태 예시':'기기 초안')}</dd></dl><div class="actions" style="margin-top:20px">${A(draft.type==='구매'?'JNL-04':'JNL-05','초안 이어쓰기','btn primary')}${B('sync','동기화 재시도')}</div></section><div class="notice amber">서버 응답이 없으면 동기화 완료로 표시하지 않습니다.</div>${B('offline',offline?'온라인 상태 확인':'오프라인 상태 확인')}`}
function upload(s){const im=s.id==='JNL-10';return `${head(s)}${isMobile(s)?'':sub(s)}<section class="panel pad"><h2>${im?'명함 이미지 첨부':'파일 선택 및 검증'}</h2><p class="small" style="margin:10px 0 20px">${im?'현재 상담일지의 바이어에게 명함 이미지를 연결합니다.':'파일 선택 후 형식을 확인하고 데이터 내용 검증을 진행합니다.'}</p>${!im?F('등록 유형',`<select>${O(s.id==='BAS-12'?['해외바이어','국내바이어','통역원']:['구매','수출'])}</select>`):''}<div class="upload" style="margin-top:20px"><strong>${im?'명함 촬영 또는 이미지 선택':'엑셀 파일 선택'}</strong><p>${im?'이미지 촬영·첨부만 제공합니다.':'실제 자료 등록은 서버 연계 후 제공됩니다.'}</p><input id="upload-file" type="file" accept="${im?'image/*':'.xlsx'}" ${im?'capture="environment"':''} aria-label="${im?'명함 이미지':'등록 파일'}"></div><div id="upload-result" aria-live="polite"></div><div class="actions" style="margin-top:20px">${B('file-check','선택 파일 확인','btn primary')}${im?A(draft.type==='구매'?'JNL-04':'JNL-05','작성 화면'):B('template','예시 엑셀 양식')}</div></section>`}
function scan(s){const auth=s.id==='COM-02';return `${head(s)}${auth?F('로그인 구분','<select id="qr-role"><option value="buyer">국내바이어</option><option value="interpreter">통역원</option></select>'):F('확인 업무',`<select>${O(s.id==='PRE-03'?['행사장 도착','공항 도착','호텔 도착','현장 매칭']:['기업·부스 연결'])}</select>`)}<div class="scanbox" style="margin-top:20px"><div id="scan-preview"><span aria-hidden="true" style="font-size:2rem">▣</span><strong>${auth?'개인 QR을 확인해 주세요.':'QR을 화면 안에 맞춰 주세요.'}</strong><p class="small">카메라를 허용하면 촬영 화면을 확인할 수 있습니다.</p></div></div><div class="actions">${B('camera','카메라 열기','btn primary')}${B('stop-camera','카메라 닫기')}</div><section class="panel pad" style="margin-top:22px">${F(auth?'발급 링크 또는 인증 코드':'QR 대상 코드',I('qr','text','','id="qr-code" placeholder="발급된 코드 입력"'))}${B('verify-qr',auth?'검토용 QR 인증':'검토용 QR 확인','btn primary','style="margin-top:16px"')}<p class="small" style="margin-top:12px">예시 코드: ${auth?'DEMO-2026':'GFAIR-2026-A01'} · 실제 인증은 서버 연계 후 제공됩니다.</p></section>`}
function companies(s){const rr=filtered(s);return `${head(s)}${filters(s)}<div class="formgrid">${rr.length?rr.map(({r,i})=>`<section class="panel pad"><div class="companycard" style="border:0;padding:0"><span class="booth">${E(r[1].replace('부스 ',''))}</span><div><strong>${E(r[0])}</strong><small>${E(r[2])}</small></div></div><p class="small">G-FAIR KOREA ${event} 참가기업 · 예시</p><div class="actions" style="margin-top:20px">${B('row','기업 상세','btn',`data-index="${i}"`)}${B('company','상담일지 작성','btn primary',`data-index="${i}"`)}</div></section>`).join(''):'<div class="empty"><strong>검색한 기업이 없습니다.</strong>조건을 변경해 주세요.</div>'}</div>`}
function companyDetail(s){const r=rows(map.get('ENT-01'))[selectedRow]||rows(map.get('ENT-01'))[0];return `${head(s,A('ENT-01','기업 목록'))}<div class="companycard"><span class="booth">${E(r[1].replace('부스 ',''))}</span><div><strong>${E(r[0])}</strong><small>${E(r[2])}</small></div></div><section class="panel pad"><h2>제품 정보</h2><div class="notice" style="margin-top:18px">홈페이지 연계정보를 바탕으로 제품·부스정보를 제공합니다.</div><dl class="detaildata"><dt>행사</dt><dd>G-FAIR KOREA ${event}</dd><dt>품목</dt><dd>${E(r[2])}</dd><dt>제품</dt><dd>친환경 생활용품 (예시)</dd><dt>제품 소개</dt><dd>일상에서 사용하는 생활용품을 제안합니다. 상세 소개는 원천정보 연계 후 제공됩니다.</dd><dt>부스</dt><dd>${E(r[1])}</dd></dl><div class="actions" style="margin-top:24px">${B('company','상담일지 작성','btn primary',`data-index="${selectedRow}"`)}</div></section>`}
function notifications(s){return `${head(s,B('read-all','모두 읽음'))}<section class="panel">${[['반려','상담일지 확인 요청','JNL-08'],['매칭','담당바이어 일정 변경','PRE-07'],['공지','행사 운영 안내','NTC-01']].map(([t,h,id],i)=>`<div style="padding:20px 22px;border-bottom:1px solid var(--line)"><div class="row">${badge(t)}<small data-read>2026-10-02 · 미확인</small></div><h3 style="margin:10px 0">${h} (예시)</h3>${A(id,'내용 확인','btn ghost')}</div>`).join('')}</section>`}
function faq(s){return `${head(s,role==='admin'?A('NTC-04','질문 등록','btn primary'):'')}${isMobile(s)?'':sub(s)}${filters(s)}<section class="panel pad">${[['개인 QR은 어떻게 이용하나요?','승인된 참가자에게 발급된 QR이나 링크로 인증합니다. 유효하지 않으면 운영 담당자에게 재발급을 요청해 주세요.','COM-03'],['오프라인에서도 일지를 작성할 수 있나요?','작성 내용은 약 30초마다 기기에 임시저장됩니다. 실제 서버 연결과 동기화 완료 후 제출해야 합니다.','JNL-09'],['반려된 일지는 어떻게 수정하나요?','내 상담일지에서 반려 사유를 확인하고 내용을 수정한 뒤 재제출합니다.','JNL-08']].filter(x=>Object.values(filter).filter(v=>v&&v!=='전체').every(v=>x.join(' ').includes(v))).map(([q,a,id])=>`<details style="padding:18px 0;border-bottom:1px solid var(--line)"><summary style="cursor:pointer;font-weight:600">${q}</summary><p style="padding:15px 0">${a}</p>${A(id,'관련 화면','btn ghost')}</details>`).join('')}</section>`}
function schedule(s){return `${head(s)}<div class="notice">담당 해외바이어 A · 영어 · 현장 매칭 확인 완료 (예시)</div><section class="panel"><div class="panelhead"><h2>오늘의 상담 일정</h2><span>10월 2일</span></div>${[['14:00','예시기업 A','A-01'],['15:00','예시기업 B','B-01']].map(([t,c,b])=>`<div style="padding:20px;border-bottom:1px solid var(--line)"><div class="row"><span class="badge blue">${t}</span><strong>${c}</strong></div><p class="small" style="margin:10px 0">해외바이어 A · ${b} 부스</p><div class="actions">${A('PRE-08','일정 상세')}${A('JNL-05','수출일지 작성','btn primary')}</div></div>`).join('')}</section><div class="actions">${A('PRE-02','방한 상태 확인')}${A('COM-05','참가·상담 이력')}</div>`}
function urgent(s){return `${head(s)}<section class="panel pad"><span class="badge pending">통역 요청 · 예시</span><h2 style="margin:15px 0">영어 통역 지원 요청</h2><dl class="detaildata"><dt>바이어</dt><dd>해외바이어 A</dd><dt>시간</dt><dd>2026-10-02 15:00</dd><dt>부스</dt><dd>A-01</dd><dt>언어</dt><dd>영어</dd></dl><p class="small" style="margin:18px 0">운영 담당자의 최종 배정 확인이 필요합니다.</p><div class="actions">${B('accept','요청 수락','btn primary')}${A('PRE-07','담당 일정')}</div></section>`}
function survey(s){return `${head(s)}<div class="notice">G-FAIR KOREA ${event} 참가자 만족도 조사 · 문항 예시</div><form id="survey-form"><section class="panel pad"><h2>행사 운영에 얼마나 만족하셨나요?</h2><div class="ratings" style="margin:22px 0">${[1,2,3,4,5].map(v=>`<label><input type="radio" name="rating" value="${v}" required>${v}</label>`).join('')}</div><div class="row small" style="justify-content:space-between"><span>매우 불만족</span><span>매우 만족</span></div>${F('의견','<textarea name="opinion" placeholder="개선이 필요한 점이나 좋았던 점"></textarea>')}<button class="btn primary" type="submit" style="margin-top:20px">검토용 제출</button></section></form>`}
function permission(s){return `${head(s)}${sub(s)}<form id="permission-form"><section class="panel"><div class="filters">${F('관리자 역할',`<select name="scope">${[['all','전체 운영'],['buy','구매 담당'],['export','수출 담당'],['stats','통계 열람']].map(([v,t])=>`<option value="${v}" ${scope===v?'selected':''}>${t}</option>`).join('')}</select>`)}</div><div class="tablewrap"><table><thead><tr><th>메뉴</th>${['조회','등록·수정','검수','승인','다운로드'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${['기본정보관리','구매상담일지','수출상담일지','대시보드·통계'].map((t,i)=>`<tr><td>${t}</td>${['조회','등록·수정','검수','승인','다운로드'].map((a,j)=>`<td><input type="checkbox" name="p${i}-${j}" aria-label="${t} ${a}" ${i===3&&j>0&&j<4?'disabled':forms['SET-02']?(Object.hasOwn(forms['SET-02'],'p'+i+'-'+j)?'checked':''):'checked'}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="formfooter"><button type="submit" class="btn primary">권한 저장</button></div></section></form><div class="notice">검토용 역할 전환입니다. 실제 접근 권한은 서버에서 검증해야 합니다.</div>`}
function field(s,label,desc,i){const n='field'+i,v=forms[s.id]?.[n]||'',required=desc.includes('필수')&&!desc.includes('시 필수'),wide=/본문|설명|내용|사유|특이|의견/.test(label);let c;if(/첨부|파일|이미지/.test(label))c=`<input type="file" name="${n}" accept="${/이미지|명함/.test(label)?'image/*':'.pdf,.docx,.xlsx,.png,.jpg'}">`;else if(wide)c=`<textarea name="${n}" placeholder="${E(label)} 입력" ${required?'required':''}>${E(v)}</textarea>`;else if(/기간/.test(label))c='<span class="row">'+I(n+'-start','date',forms[s.id]?.[n+'-start']||'','aria-label="'+E(label)+' 시작일"')+I(n+'-end','date',forms[s.id]?.[n+'-end']||'','aria-label="'+E(label)+' 종료일"')+'</span>';else if(/일시|상담일|날짜/.test(label))c=I(n,'datetime-local',v,required?'required':'');else if(/여부|긴급/.test(label))c=`<select name="${n}">${O(['사용','사용 안 함'],v)}</select>`;else if(/QR.*상태/.test(label))c='<select name="'+n+'">'+O(['미발급','활성','비활성'],v)+'</select>';else if(label==='검수 상태')c=`<select name="${n}">${O(['대기','승인','반려'],v||'대기')}</select>`;else if(/상태/.test(label))c=`<select name="${n}">${O(/현재|방한/.test(label)?['입국예정','공항도착','이동중','호텔도착','체크인','행사장도착','상담진행']:['준비','운영','종료','대기','승인','반려'],v)}</select>`;else if(/대상 역할|대상 구분|응답자|대상.*역할/.test(label))c=`<select name="${n}">${O(['전체','국내바이어','해외바이어','통역원'],v)}</select>`;else if(/유형|구분|채널/.test(label)&&desc.includes('/'))c=`<select name="${n}">${O(desc.split('/').map(x=>x.trim().replace(/\(.*?\)/g,'')).filter(x=>x.length<35),v)}</select>`;else if(/금액|상담액|추진액/.test(label))c=I(n,'number',v,'min="0" step="any"');else if(/연계정보|조회|로그인정보|자동/.test(desc))c=I(n,'text',v||(/행사/.test(label)?'G-FAIR KOREA '+event:/기업/.test(label)?'예시기업 A':/바이어/.test(label)?'해외바이어 A':'미등록'),'readonly class="readonly"');else c=I(n,'text',v,`placeholder="${E(label)} 입력" ${required?'required':''}`);return F(label,c,required,wide)}
function form(s){if(['JNL-02','JNL-08'].includes(s.id))return jDetail(s);if(s.id==='ENT-02')return companyDetail(s);if(s.id==='JNL-12')return `${head(s)}${sub(s)}<section class="panel pad"><h2>상담일지 다운로드</h2><p class="small" style="margin:12px 0 24px">현재 행사와 담당 범위의 예시 일지를 출력합니다.</p><div class="actions">${B('xlsx','엑셀 다운로드','btn primary')}${B('print','PDF 출력')}${A('JNL-01','목록')}</div></section>`;return `${head(s)}${isMobile(s)?'':sub(s)}<form id="generic-form"><section class="panel"><div class="panelhead"><h2>기본 정보</h2><span>예시 입력 화면</span></div><div class="panel pad" style="border:0;margin:0"><div class="formgrid">${(s.ui.fields||[]).map(([l,d],i)=>field(s,l,d,i)).join('')}</div></div><div class="formfooter">${(s.ui.actions||[]).map((a,i)=>B('form-action',a,i===0?'btn primary':'btn',`data-label="${E(a)}"`)).join('')}</div></section></form>${s.id==='NTC-05'?'<div class="notice amber">검토용 화면에서는 SMS를 실제로 발송하지 않습니다.</div>':''}<div id="form-result" aria-live="polite"></div>`}
function login(){return `<div class="login-page"><section class="login-brand"><a class="brand" href="#MON-01">G<span>·</span>FAIR<small>KOREA</small></a><div><h1>상담의 시작부터<br>성과의 확인까지.</h1><p>G-FAIR KOREA 구매 및 수출 상담시스템<br>참가정보, 상담일지, 현장 운영을 한곳에서 관리합니다.</p></div><footer>G-FAIR KOREA · 구매 및 수출 상담시스템</footer></section><main class="login-form" id="content"><div><span class="badge blue">관리자</span><h1 style="margin-top:18px">로그인</h1><p class="subtitle">관리자 계정으로 접속해 주세요.</p><form id="login-form">${F('아이디',I('username','text','','autocomplete="username" placeholder="아이디" required'),true)}${F('비밀번호',I('password','password','','autocomplete="current-password" placeholder="비밀번호" required'),true)}<button type="submit" class="btn primary">검토용 로그인</button></form><div class="login-grid"><strong>참가자 이용</strong><a href="#COM-02">국내바이어·통역원 QR 로그인</a><a href="#screens">전체 화면 목록</a></div><div class="notice">실제 인증 없이 예시 화면으로 이동합니다. 실제 비밀번호를 입력하지 마세요.</div></div></main></div>`}
function screenList(){return `${top()}<main class="screen-browser" id="content"><div class="pagehead"><div><h1>G-FAIR 화면 목록</h1><p class="subtitle">SB v0.2 · 9개 파일 · 67개 화면</p></div>${A('MON-01','대시보드','btn primary')}</div>${F('화면 검색','<input type="search" id="screen-search" placeholder="화면명 또는 화면코드">')}<div>${groups.map(g=>`<section data-screen-group><h2>${g.name} <small>${g.screens.length}개 화면</small></h2><div class="screen-list" style="margin-top:15px">${g.screens.map(s=>`<a href="#${s.id}" data-screen-item data-search="${E(s.id+' '+s.title)}"><span class="screenid">${s.id}</span><strong>${E(s.title)}</strong><small>${E(s.role)}</small></a>`).join('')}</div></section>`).join('')}</div></main>`}
function stop(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}
function render(){stop();current=decodeURIComponent(location.hash.slice(1))||document.body.dataset.screen||'MON-01';if(current==='screens'){root.innerHTML=screenList();return}const s=map.get(current);if(!s){root.innerHTML=`${top()}<main class="content" id="content"><div class="empty"><strong>화면을 찾을 수 없습니다.</strong>${A('screens','화면 목록')}</div></main>`;return}document.title=s.title+' · G-FAIR KOREA';if(s.id==='COM-01'){root.innerHTML=login();return}let body;if(['JNL-04','JNL-05','JNL-06'].includes(s.id))body=write(s);else if(s.id==='JNL-09')body=sync(s);else if(['JNL-10','JNL-11','BAS-12'].includes(s.id))body=upload(s);else if(['COM-02','JNL-03','PRE-03'].includes(s.id))body=scan(s);else if(s.id==='COM-03')body=`${head(s)}<div class="notice danger"><div><strong>인증을 완료할 수 없습니다.</strong><p>QR의 유효 여부와 행사 참가 승인을 확인해 주세요.</p></div></div><section class="panel pad"><h2>이용 전 확인사항</h2><p style="margin:16px 0">카메라를 허용하거나 발급된 링크로 다시 시도해 주세요. 미승인·비활성 계정은 운영 담당자의 확인이 필요합니다.</p><div class="actions">${A('COM-02','다시 인증','btn primary')}${B('contact','문의 안내')}</div></section>`;else if(s.id==='PRE-07')body=schedule(s);else if(s.id==='NTC-06')body=urgent(s);else if(s.id==='NTC-08')body=survey(s);else if(s.id==='SET-02')body=permission(s);else if(s.id==='MON-07'||s.kind==='dashboard'||s.ui.metrics)body=dash(s);else if(['list','matrix'].includes(s.kind))body=list(s);else body=form(s);root.innerHTML=shell(s,body);if(window.lucide)lucide.createIcons({attrs:{width:20,height:20,'stroke-width':1.6}})}
function modal(title,body,action='close',label='확인'){document.getElementById('dialog-content').innerHTML=`<div class="dialoghead"><h2>${E(title)}</h2>${B('close','닫기','btn ghost')}</div><div class="dialogbody">${body}</div><div class="dialogactions">${B('close','취소')}${B(action,label,'btn primary')}</div>`;dialog.showModal()}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csv(){const s=map.get(current);let rr;if(current.startsWith('JNL')||s?.kind==='dashboard')rr=[['일지번호','유형','기업','부스','바이어','작성자','제출 일자','상태','상담액','계약추진액','통화'],...jRows({...s,id:current==='JNL-07'?'JNL-07':'JNL-01'}).map(j=>[j.id,j.type,j.company,j.booth,j.buyer,j.writer,j.time,j.status,j.amount,j.contract,j.currency])];else rr=[s.ui.columns||['항목','값'],...rows(s)];const text='\ufeff'+rr.map(r=>r.map(v=>{let t=String(v??'');if(/^[=+@-]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"'}).join(',')).join('\r\n');download(new Blob([text],{type:'text/csv;charset=utf-8'}),'G-FAIR_'+current+'_예시.csv');toast('예시 데이터를 CSV로 다운로드했습니다.')}
function approve(reject){const j=journals.find(j=>j.id===selected);if(!j||j.status!=='검수 대기')return toast('최신 처리 상태를 다시 확인해 주세요.');if(scope==='stats'||scope!=='all'&&scope!==(j.type==='구매'?'buy':'export'))return toast('해당 유형의 검수 권한이 없습니다.');if(reject){const v=document.getElementById('reject-reason')?.value.trim();if(!v){document.getElementById('reject-reason')?.focus();return toast('반려 사유를 입력해 주세요.')}j.reason=v}j.status=reject?'반려':'승인 완료';j.history.unshift([j.status,'운영 관리자 · '+new Date().toLocaleTimeString('ko-KR')]);log(j.status,j.id);render();toast('검토용 일지를 '+j.status+' 상태로 변경했습니다.')}
function genericAction(label){const s=map.get(current),f=document.getElementById('generic-form');if(/취소|목록/.test(label)){nav(groups.find(g=>g.key===s.group).screens[0].id);return}if(/다운로드/.test(label)){if(label.includes('엑셀'))xlsx();else if(label.includes('PDF'))window.print();else csv();return}if(label==='QR 확인'){nav('PRE-03');return}if(label==='긴급 호출'||label==='매칭 안내'){nav('NTC-05');return}if(label.includes('이력')){modal('처리 이력',logs.length?`<div class="timeline">${logs.slice(0,8).map(x=>`<div><strong>${E(x.action)}</strong><small>${E(x.target+' · '+x.time)}</small></div>`).join('')}</div>`:'<p>이 화면에서 아직 처리한 내용이 없습니다.</p>');return}if(label==='미리보기'){modal(label,`<dl class="detaildata">${[...new FormData(f)].filter(([,v])=>typeof v==='string').map(([k,v])=>`<dt>${E(s.ui.fields[Number(k.replace('field',''))]?.[0]||k)}</dt><dd>${E(v||'미입력')}</dd>`).join('')}</dl>`);return}if(label==='문항 추가'){const g=f.querySelector('.formgrid'),i=g.children.length;g.insertAdjacentHTML('beforeend',F('추가 문항 '+(i+1),I('field'+i,'text','','required'),true));return}if(label==='발송'){modal('발송 대상 확인','<p>예시 대상과 내용을 확인합니다. 실제 SMS는 발송하지 않습니다.</p>','demo-send','검토 완료');return}if(['승인','반려','비활성화','활성화','신규 발급','재발급'].includes(label)){const ix=s.ui.fields.findIndex(x=>/상태/.test(x[0]));const el=f.elements['field'+ix];if(el?.tagName==='SELECT'){const val={'승인':'승인','반려':'반려','비활성화':'비활성','활성화':'활성','신규 발급':'활성','재발급':'활성'}[label];if([...el.options].some(o=>o.value===val))el.value=val}}if(label==='QR 관리'){nav('BAS-14');return}if(label==='반려'){const ix=s.ui.fields.findIndex(x=>x[0].includes('반려 사유'));if(ix>=0&&!f.elements['field'+ix].value.trim())return toast('반려 사유를 입력해 주세요.');}if(!f.reportValidity())return;const fd=new FormData(f);for(const [k,v] of fd){if(k.endsWith('-start')&&v&&fd.get(k.replace('-start','-end'))&&v>fd.get(k.replace('-start','-end')))return toast('종료일은 시작일 이후로 입력해 주세요.');}forms[current]=Object.fromEntries([...new FormData(f)].filter(([,v])=>typeof v==='string'));log(label,current);document.getElementById('form-result').innerHTML=`<div class="notice"><strong>${E(label)} 확인 완료</strong><span>현재 화면의 예시 상태에 반영했습니다.</span></div>`;toast(label+' 예시 상태를 반영했습니다.')}
function action(label){const s=map.get(current),paths={'신규 행사':'BAS-02','등록':current==='SET-01'?undefined:target[current],'상세·수정':target[current],'상세':target[current],'일괄등록':'BAS-12','참가이력':'BAS-11','방한정보':'PRE-01','매칭 등록':'PRE-05','매칭 상세':'PRE-05','사전 안내':'NTC-05','방한 상세':'PRE-02','긴급 호출':'NTC-05','자료 연결':'NTC-03','대상 안내':'NTC-05','상세·권한':'SET-02','일지 상세':'JNL-02','검수 대상':'JNL-01','일괄 업로드':'JNL-11','바이어 출석':'MON-05','일지 현황':'JNL-01','방한 현황':'PRE-01','매칭 현황':'MON-04','구매 대시보드':'MON-02','수출 대시보드':'MON-03','연도별 실적':'STA-02','바이어 통계':'STA-03','품목·기관 통계':'STA-04','내역 조회':'BAS-11','상세 분류':'STA-04','공지 등록':'NTC-04','질문 등록':'NTC-04','자료 등록':'NTC-04','알림 발송':'NTC-05','연결화면':'NTC-06','내용 확인':'NTC-06','기업 상세':'ENT-02','선택 행사 진입':'MON-01','내 상담일지':'JNL-07','이력 상세':'JNL-08','새 일지':effective(s)==='interpreter'?'JNL-05':'JNL-04','초안 이어쓰기':draft.type==='구매'?'JNL-04':'JNL-05','일정 상세':'PRE-07','수출일지 작성':'JNL-05'};
if(/다운로드/.test(label)){if(label.includes('PDF'))window.print();else if(label.includes('엑셀'))xlsx();else csv();return}if(paths[label]){nav(paths[label]);return}if(/출석|보정|QR/.test(label)){modal(label,`${F('대상',`<select id="att-person">${O(rows(s).map(r=>r[0]))}</select>`)}${F('처리 상태','<select id="att-state"><option>출석</option><option>미출석</option></select>')}${F('사유','<textarea id="att-reason" placeholder="확인 또는 보정 사유" required></textarea>')}`,'att-confirm','상태 반영');return}if(/등록/.test(label)){modal(label,`${F('이름 또는 제목',I('title','text','','id="new-title" required'),true)}${F('내용','<textarea id="new-content"></textarea>')}`,'add-row','예시 등록');return}modal(label,`<p>${E(s.summary)}</p><p class="small" style="margin-top:12px">현재 조회 결과 ${rows(s).length}건을 기준으로 확인합니다.</p>`,'confirm-action','확인')}

function exportRows(){const s=map.get(current);if(current.startsWith('JNL')||s?.kind==='dashboard')return [['일지번호','유형','기업','부스','바이어','작성자','제출 일자','상태','상담액','계약추진액','통화'],...jRows({...s,id:current==='JNL-07'?'JNL-07':'JNL-01'}).map(j=>[j.id,j.type,j.company,j.booth,j.buyer,j.writer,j.time,j.status,Number(j.amount),Number(j.contract),j.currency])];return [s.ui.columns||['항목','값'],...rows(s)]}
async function xlsx(){try{download(await GFAIRWorkbook.write(exportRows()),'G-FAIR_'+current+'_예시.xlsx');toast('예시 데이터를 엑셀로 다운로드했습니다.')}catch{toast('엑셀 생성에 실패했습니다. 다시 시도해 주세요.')}}
async function template(){const rr=current==='BAS-12'?[['내부번호','이름','역할','행사'],['DEMO-001','예시 참가자','국내바이어','2026']]:[['유형','기업','바이어','상담내용','상담액','통화'],['구매','예시기업 A','국내바이어 A','예시 상담내용',1000000,'KRW']];download(await GFAIRWorkbook.write(rr),'G-FAIR_검토용양식.xlsx');toast('검토용 예시 양식입니다. 실제 등록 양식은 확정 후 적용합니다.')}
async function checkUpload(){const f=document.getElementById('upload-file').files[0];if(!f)return toast('파일을 먼저 선택해 주세요.');const el=document.getElementById('upload-result');if(current==='JNL-10'){el.innerHTML='<div class="notice '+(f.type.startsWith('image/')?'':'danger')+'" style="margin-top:20px">'+E(f.name)+' · '+(f.type.startsWith('image/')?'첨부할 수 있는 이미지입니다.':'이미지 파일을 선택해 주세요.')+'</div>';return}if(!/\.xlsx$/i.test(f.name))return toast('검토용 화면은 XLSX 형식을 읽을 수 있습니다.');try{const rr=await GFAIRWorkbook.read(f),header=rr[0]||[],cols=current==='BAS-12'?['내부번호','이름','역할','행사']:['유형','기업','바이어','상담내용','상담액','통화'];if(!cols.every(c=>header.includes(c)))throw Error('검토용 예시 양식의 열 이름을 확인해 주세요.');const indices=cols.map(c=>header.indexOf(c)),good=[],bad=[],seen=new Set();rr.slice(1).forEach((r,i)=>{const data=indices.map(j=>r[j]??'');let error='';if(data.some(v=>String(v).trim()===''))error='필수값 누락';else if(current==='BAS-12'){if(!['국내바이어','해외바이어','통역원'].includes(data[2]))error='역할 형식';else if(seen.has(data[0]))error='내부번호 중복';else seen.add(data[0]);}else if(!['구매','수출'].includes(data[0]))error='상담 유형';else if(!Number.isFinite(Number(data[4]))||Number(data[4])<0)error='금액 형식';else if(!['KRW','USD','EUR'].includes(data[5]))error='통화 형식';(error?bad:good).push({line:i+2,data,error})});uploadData={route:current,good,bad};el.innerHTML='<div class="notice" style="margin-top:20px">파일 검증: 정상 '+good.length+'건 · 오류 '+bad.length+'건 · 예시 양식 기준</div><div class="tablewrap"><table><thead><tr><th>행번호</th><th>주요 값</th><th>결과</th></tr></thead><tbody>'+[...good,...bad].slice(0,20).map(x=>'<tr><td>'+x.line+'</td><td>'+E(x.data.slice(0,3).join(' / '))+'</td><td>'+badge(x.error||'정상')+'</td></tr>').join('')+'</tbody></table></div>'+(good.length?B('register-upload','정상 건 예시 등록','btn primary','style="margin-top:20px"'):'');toast('검토용 양식의 내용을 확인했습니다.')}catch(e){uploadData=null;el.innerHTML='<div class="notice danger" style="margin-top:20px">'+E(e.message)+'</div>'}}
function registerUpload(){if(!uploadData||uploadData.route!==current)return toast('파일 검증을 먼저 진행해 주세요.');if(current==='BAS-12'){for(const x of uploadData.good){const d=x.data,key={'국내바이어':'BAS-05','해외바이어':'BAS-03','통역원':'BAS-07'}[d[2]],rr=rows(map.get(key));rr.push(d[2]==='국내바이어'?[d[0],d[1],'미등록','대기','미발급',d[3]]:d[2]==='해외바이어'?[d[0],d[1],'미등록','미등록',d[3],'대기','미발급']:[d[0],d[1],'미등록',d[3],'미발급','미등록','대기']);lists[key]=rr;}}else{for(const x of uploadData.good){const d=x.data;journals.push({id:'GF-UPLOAD-'+journals.length,type:d[0],company:d[1],booth:'미등록',buyer:d[2],writer:'예시 업로드',time:journalSubmittedAt(),status:'검수 대기',amount:Number(d[4]),contract:0,currency:d[5],content:d[3],reason:'',history:[['예시 업로드','운영 관리자']]})}}log('정상 건 예시 등록',uploadData.good.length+'건');uploadData=null;toast('정상 건을 예시 목록에 추가했습니다. 승인 처리와 실제 서버 등록은 하지 않았습니다.');nav(current==='BAS-12'?'BAS-05':'JNL-01')}

async function camera(){if(!navigator.mediaDevices?.getUserMedia)return toast('카메라를 사용할 수 없습니다. 코드 입력을 이용해 주세요.');try{stop();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const el=document.getElementById('scan-preview');if(!el){stop();return}el.innerHTML='<video id="camera-video" autoplay playsinline muted aria-label="QR 카메라 미리보기"></video><p class="small">실제 QR 인식은 서버 연계 후 제공됩니다.</p>';document.getElementById('camera-video').srcObject=stream}catch{toast('카메라 권한을 확인하거나 코드 입력을 이용해 주세요.')}}
root.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,s=map.get(current);if(a==='menu'){menu=!menu;render()}else if(a==='reset'){filter={};render()}else if(a==='kind'){kind=b.dataset.kind;render()}else if(a==='refresh'){render();toast('예시 화면을 새로고침했습니다.')}else if(a==='j-detail'){selected=b.dataset.id;nav(b.dataset.personal==='true'?'JNL-08':'JNL-02')}else if(a==='approve')approve(false);else if(a==='reject')approve(true);else if(a==='row'){selectedRow=Number(b.dataset.index);if(target[current])nav(target[current]);else modal('상세 정보',`<dl class="detaildata">${(rows(s)[selectedRow]||[]).map((v,i)=>`<dt>${E(s.ui.columns[i])}</dt><dd>${E(v)}</dd>`).join('')}</dl>`)}else if(a==='action')action(b.dataset.label);else if(a==='form-action')genericAction(b.dataset.label);else if(a==='xlsx')await xlsx();else if(a==='new-journal'){draft={id:'GF-DRAFT-'+Date.now(),type:effective(s)==='interpreter'?'수출':'구매',company:'예시기업 A',booth:'A-01',content:'',date:'2026-10-02T14:30',amount:'',contract:'',currency:effective(s)==='interpreter'?'USD':'KRW',tags:[],followup:''};submitted=false;savedAt='';resubmit=null;nav(draft.type==='구매'?'JNL-04':'JNL-05')}else if(a==='csv')csv();else if(a==='print')window.print();else if(a==='save'){if(save())toast('작성 내용을 이 기기에 임시저장했습니다.')}else if(a==='company'){const r=rows(map.get('ENT-01'))[Number(b.dataset.index)]||rows(map.get('ENT-01'))[0];draft.company=r[0];draft.booth=r[1].replace('부스 ','');nav(effective(s)==='interpreter'?'JNL-05':'JNL-04')}else if(a==='edit-journal'){const j=journals.find(j=>j.id===selected);draft={...draft,type:j.type,company:j.company,booth:j.booth,content:j.content,amount:j.amount,contract:j.contract,currency:j.currency};resubmit=j.id;nav(j.type==='구매'?'JNL-04':'JNL-05')}else if(a==='remove-image'){URL.revokeObjectURL(image.url);image=null;render()}else if(a==='offline'){offline=!offline;render()}else if(a==='sync')toast(connected()?'서버 연결 전입니다. 기기 초안은 유지됩니다.':'오프라인입니다. 연결 후 다시 확인해 주세요.');else if(a==='camera')await camera();else if(a==='stop-camera'){stop();render()}else if(a==='verify-qr'){const code=document.getElementById('qr-code').value.trim();if(code===(current==='COM-02'?'DEMO-2026':'GFAIR-2026-A01')){if(current==='COM-02'){role=document.getElementById('qr-role').value;nav(role==='buyer'?'JNL-07':'PRE-07')}else if(current==='PRE-03')modal('예시 QR 대상 확인','<p>해외바이어 A · G-FAIR KOREA 2026</p><p class="small">현재 행사와 대상이 일치합니다.</p>','qr-confirm','예시 완료 확인');else{draft.company='예시기업 A';draft.booth='A-01';nav(effective(s)==='interpreter'?'JNL-05':'JNL-04')}}else if(current==='COM-02')nav('COM-03');else toast('현재 행사와 QR 대상 코드를 확인해 주세요.')}else if(a==='contact')modal('운영 담당자 문의','<p>운영 담당자의 연락처는 행사 안내에서 확인해 주세요.</p><p class="small">실제 문의 연락처는 제공 자료에 따라 반영합니다.</p>');else if(a==='logout')modal('로그아웃',`<p>${savedAt?'이 기기에 저장된 검토용 초안이 정리됩니다.':'검토용 화면에서 로그아웃할까요?'}</p>`,'logout-confirm','로그아웃');else if(a==='read-all'){root.querySelectorAll('[data-read]').forEach(x=>x.textContent='2026-10-02 · 읽음');toast('예시 알림을 읽음으로 변경했습니다.')}else if(a==='accept')modal('통역 요청 수락','<p>현재 담당 일정과 중복되지 않는지 확인해 주세요.</p><p class="small">최종 매칭은 운영 담당자가 확정합니다.</p>','accept-confirm','수락 확인');else if(a==='file-check'){await checkUpload()}else if(a==='template'){await template()}else if(a==='register-upload'){registerUpload()}});
document.getElementById('dialog-content').addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='close'){dialog.close();return}if(a==='logout-confirm'){save();try{sessionStorage.removeItem('gfair-draft')}catch{}savedAt='';submitted=false;draft={...draft,content:'',amount:'',contract:'',tags:[]};if(image)URL.revokeObjectURL(image.url);image=null;dialog.close();role='admin';nav('COM-01');return}if(a==='add-row'){const title=document.getElementById('new-title').value.trim();if(!title)return toast('이름 또는 제목을 입력해 주세요.');const s=map.get(current),rr=rows(s);rr.push(s.ui.columns.map((_,i)=>i===0?title:i===1?'G-FAIR KOREA '+event:'미등록'));lists[current]=rr;log('예시 등록',title);dialog.close();render();toast('예시 목록에 추가했습니다.');return}if(a==='att-confirm'){const reason=document.getElementById('att-reason').value.trim();if(!reason)return toast('처리 사유를 입력해 주세요.');const s=map.get(current),rr=rows(s),person=document.getElementById('att-person').value,i=rr.findIndex(r=>r[0]===person),j=s.ui.columns.findIndex(c=>/출석상태/.test(c));if(i>=0&&j>=0)rr[i][j]=document.getElementById('att-state').value;lists[current]=rr;log('출석 상태 변경',person);dialog.close();render();toast('예시 출석 상태를 반영했습니다.');return}dialog.close();if(a==='accept-confirm'){log('통역 요청 수락','해외바이어 A');toast('수락 상태를 확인했습니다. 최종 배정은 담당자가 확정합니다.');nav('PRE-07')}else if(a==='demo-send'){log('발송 검토',current);toast('검토를 완료했습니다. 실제 SMS는 발송하지 않았습니다.')}else if(a==='qr-confirm'){log('QR 완료 확인 예시','해외바이어 A');toast('예시 완료 확인 이력을 남겼습니다.')}else{log('작업 확인',current);toast('예시 화면의 작업을 확인했습니다.')}});
root.addEventListener('submit',ev=>{ev.preventDefault();const f=ev.target;if(f.id==='filter-form'||f.id==='journal-filter'){filter=Object.fromEntries(new FormData(f));for(const key of new Set([...f.querySelectorAll('[data-multi-filter] input[type=checkbox]')].map(e=>e.name)))filter[key]=new FormData(f).getAll(key);render()}else if(f.id==='login-form'){if(!f.reportValidity())return;f.reset();role='admin';nav('MON-01')}else if(f.id==='draft-form'){if(!f.reportValidity())return;save();if(current!=='JNL-06'){draft.currency=draft.type==='구매'?'KRW':'USD';nav('JNL-06');return}if(!connected())return toast('오프라인입니다. 기기 초안은 저장했으며 제출할 수 없습니다.');if(event==='2025')return toast('종료 행사에서는 예시 일지를 제출할 수 없습니다.');if(!draft.content.trim())return toast('상담내용을 먼저 작성해 주세요.');if(!draft.company)return toast('상담기업을 선택해 주세요.');let j=resubmit?journals.find(j=>j.id===resubmit):null;if(j){Object.assign(j,{content:draft.content,amount:draft.amount,contract:draft.contract,currency:draft.currency,time:journalSubmittedAt(),status:'검수 대기'});j.history.unshift(['재제출 예시',new Date().toLocaleTimeString('ko-KR')]);resubmit=null}else if(!submitted)journals.unshift({id:'GF-DEMO-'+(journals.length+1),type:draft.type,company:draft.company,booth:draft.booth,buyer:draft.type==='구매'?'국내바이어 A':'해외바이어 A',writer:draft.type==='구매'?'국내바이어 A':'통역원 A',time:journalSubmittedAt(),status:'검수 대기',amount:draft.amount,contract:draft.contract,currency:draft.currency,content:draft.content,reason:'',history:[['검토용 제출',new Date().toLocaleTimeString('ko-KR')]]});submitted=true;log('검토용 제출',draft.id);toast('예시 목록에 반영했습니다. 실제 서버 제출은 하지 않았습니다.');nav('JNL-07')}else if(f.id==='permission-form'){scope=new FormData(f).get('scope');forms['SET-02']=Object.fromEntries(new FormData(f));log('검토용 담당 범위 변경',scope);toast('화면의 담당 범위를 적용했습니다.');render()}else if(f.id==='survey-form'){log('예시 설문 제출','참가자');f.innerHTML='<section class="panel pad"><h2>참여해 주셔서 감사합니다.</h2><p style="margin:12px 0">검토용 설문 제출 상태입니다.</p><a href="#NTC-07" class="btn primary">알림센터</a></section>';toast('예시 응답을 확인했습니다.')}});
