function dashboardArea(type){const buy=type==='구매',d=dashboardExample[buy?'buy':'export'],colors=['#919191','#a9a9a9','#949494','#bebebe'],itemLabels=['식품','주방','레저','미용','패션','테크','인테리어','전자기기','기타'];return `<section class="overview-area" aria-label="${type}상담 대시보드"><h2><i></i>${type}상담 대시보드</h2><div class="overview-two">${dashTile('출석 예정 '+(buy?'국내':'해외')+' 바이어 수',d.expected)}${dashTile('상담 진행 중인 '+(buy?'국내 바이어':'통역원')+' 수',d.active)}</div><div class="overview-two"><article class="overview-chart"><h3>${buy?'국내':'해외'} 바이어 출결 현황</h3>${dashboardStack(['미출석','출석'],d.attendance,colors)}</article><article class="overview-chart"><div class="overview-section-head"><h3>${buy?'분류별 국내 바이어 수 통계':'해외 바이어 방한 정보'}</h3>${!buy?A('PRE-01','상세 보기','btn ghost'):''}</div>${buy?dashboardStack(['리빙','뷰티','식품','기타'],d.categories,colors):`<ul class="overview-travel">${d.travel.map(([t,v])=>`<li><span>${E(t)}</span><b>${v}명</b></li>`).join('')}</ul>`}</article></div><div class="overview-three">${dashTile((buy?'국내':'해외')+' 바이어 상담 건수',d.count,'건')}${dashTile((buy?'국내':'해외')+' 바이어 상담액',d.amount,d.amountUnit)}${dashTile(buy?'국내 바이어 계약 추진액':'수출상담 계약 추진액',d.contractAmount,d.contractUnit)}</div><div class="overview-two"><article class="overview-chart"><h3>${type}상담일지 현황</h3><div class="overview-status"><div class="overview-donut" style="background:conic-gradient(#a9a9a9 0 ${d.status[0]/d.count*100}%,#bebebe ${d.status[0]/d.count*100}% ${(d.status[0]+d.status[1])/d.count*100}%,#919191 0)" role="img" aria-label="승인 완료 ${d.status[0]}건, 검수 대기 ${d.status[1]}건, 반려 ${d.status[2]}건"><span>${d.count}<small>등록 건수</small></span></div><ul class="overview-legend status-legend">${['승인 완료','검수 대기','반려'].map((t,i)=>`<li><i style="background:${['#a9a9a9','#bebebe','#919191'][i]}"></i><span>${t}</span><b>${d.status[i]}건</b></li>`).join('')}</ul></div></article><article class="overview-chart"><div class="overview-section-head"><h3>품목별 상담 현황</h3><small>단위: 건</small></div><div class="overview-bars" role="img" aria-label="${E(itemLabels.map((t,i)=>t+' '+d.items[i]+'건').join(', '))}">${itemLabels.map((t,i)=>`<div><b>${d.items[i]}</b><span style="height:${d.items[i]}px"></span><small>${t}</small></div>`).join('')}</div></article></div>${dashboardPending(type)}<p class="overview-note">예시 통계 · 상담액과 계약 추진액은 원통화 기준</p></section>`}
